{
  "schema_version": "spine_v1",
  "chapters": [
    {
      "chapter_id": 1,
      "title": "The 1% Chance",
      "goal": "Survive the Isekai induction by landing a logic-defying critical hit on the Tutorial Boss.",
      "chapter_role": "hook",
      "stakes_shift": "From a confused victim of a summoning accident to a system-flagged anomaly with a bounty.",
      "bridge": {
        "from_prev": "N/A",
        "to_next": "Artie enters the first starter town with a 'Red Name' status and a broken agility stat."
      },
      "pacing": {
        "intensity": 4,
        "tempo": "rush",
        "expected_scene_count": 8
      }
    },
    {
      "chapter_id": 2,
      "title": "Min-Maxing for Cowards",
      "goal": "Identify the 'Hit & Run' passive exploit and acquire the first piece of 'Agility-only' gear.",
      "chapter_role": "setup",
      "stakes_shift": "From an accidental killer to an aspiring exploiter looking to turn a glitch into a career.",
      "bridge": {
        "from_prev": "Arrival in Oakhaven with a red name and zero survival skills.",
        "to_next": "A quest for a 'Speedster's Cloak' leads Artie into a high-level dungeon far above his bracket."
      },
      "pacing": {
        "intensity": 2,
        "tempo": "steady",
        "expected_scene_count": 10
      }
    },
    {
      "chapter_id": 3,
      "title": "The Kiting King",
      "goal": "Clear the 'Snail-Shell Catacombs' by using high-speed kiting to avoid every single point of damage.",
      "chapter_role": "trial",
      "stakes_shift": "Proving that a 'zero-health' build is viable, provided he never stops moving.",
      "bridge": {
        "from_prev": "Entering the catacombs with 1 HP but maxed-out movement speed.",
        "to_next": "Looting a 'Key of the Unseen' which alerts the local Player-Run Guild to his presence."
      },
      "pacing": {
        "intensity": 3,
        "tempo": "steady",
        "expected_scene_count": 12
      }
    },
    {
      "chapter_id": 4,
      "title": "Patch Notes Pending",
      "goal": "Evade a high-level 'Player Moderator' sent to investigate his 'glitched' damage output.",
      "chapter_role": "reversal",
      "stakes_shift": "The threat shifts from monster-slaying to surviving a direct System intervention.",
      "bridge": {
        "from_prev": "The Moderator spawns at the Catacombs exit to perform a 'Manual Audit'.",
        "to_next": "Artie is forced to flee into the 'Dead-Zone,' a region where the System is unstable."
      },
      "pacing": {
        "intensity": 5,
        "tempo": "rush",
        "expected_scene_count": 10
      }
    },
    {
      "chapter_id": 5,
      "title": "The Tank and the Turbo",
      "goal": "Form an uneasy alliance with 'Bulwark,' a tank who needs Artie's DPS to clear a Dead-Zone gate.",
      "chapter_role": "alliance",
      "stakes_shift": "From a solo runner to a team player who must trust someone else to take the hits.",
      "bridge": {
        "from_prev": "Meeting Bulwark in the unstable ruins while hiding from the Moderator.",
        "to_next": "Reaching the 'Heart of the Glitch' to reset their criminal status."
      },
      "pacing": {
        "intensity": 2,
        "tempo": "slow_burn",
        "expected_scene_count": 10
      }
    },
    {
      "chapter_id": 6,
      "title": "Critical Failure",
      "goal": "Defeat the regional Dead-Zone Guardian by 'overclocking' the environment's physics.",
      "chapter_role": "confrontation",
      "stakes_shift": "The survival of the party and the potential to ascend to a new tier of 'System-Breaker'.",
      "bridge": {
        "from_prev": "The Guardian blocks the only exit back to the stable world.",
        "to_next": "The Guardian's defeat shatters the zone boundaries, causing a massive server-wide event."
      },
      "pacing": {
        "intensity": 5,
        "tempo": "rush",
        "expected_scene_count": 12
      }
    },
    {
      "chapter_id": 7,
      "title": "Hit, Run, Repeat",
      "goal": "Secure a new identity in the capital city while the System logs are purged by the explosion.",
      "chapter_role": "aftermath",
      "stakes_shift": "Transitioning from a local nuisance to a legendary figure in the game's underground.",
      "bridge": {
        "from_prev": "Emerging from the Dead-Zone with massive XP and a purged bounty.",
        "to_next": "The next expansion opens, and Artie realizes his 'Crit' key is the only way in."
      },
      "pacing": {
        "intensity": 3,
        "tempo": "steady",
        "expected_scene_count": 8
      }
    }
  ]
}

